<script setup lang="ts">
import { ref } from "vue";
import { http } from "@/utils/http";
type Job = Record<string, any>; const tab = ref("jobs"); const rows = ref<Job[]>([]); const loading = ref(false); const error = ref(""); const detail = ref<any>(false);
async function load() { loading.value = true; try { const result = await http.get<unknown, unknown>("/background-tasks"); rows.value = Array.isArray(result) ? result as Job[] : []; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "AI 作业加载失败"; } finally { loading.value = false; } }
load();
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">作业、Trace 与用量</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">只展示允许公开的运维元数据，Prompt、Credential 和私密内容默认脱敏。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="warning" show-icon :closable="false" class="mb-4"/><el-tabs v-model="tab"><el-tab-pane label="作业" name="jobs"/><el-tab-pane label="Trace" name="trace"/><el-tab-pane label="用量" name="usage"/></el-tabs><el-card shadow="never" class="mt-4"><template v-if="tab === 'jobs'"><el-empty v-if="!rows.length" description="暂无 AI 作业"/><el-table v-else :data="rows" stripe><el-table-column prop="id" label="Job ID" min-width="220"/><el-table-column prop="type" label="类型" width="150"/><el-table-column prop="status" label="状态" width="130"/><el-table-column prop="progress" label="进度" width="160"/><el-table-column prop="createdAt" label="创建时间" min-width="180"/><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link @click="detail = row">详情</el-button></template></el-table-column></el-table></template><template v-else-if="tab === 'trace'"><el-form inline><el-form-item label="Trace ID"><el-input placeholder="仅搜索授权范围"/></el-form-item><el-form-item label="状态"><el-select placeholder="全部"><el-option label="全部" value="all"/><el-option label="成功" value="success"/><el-option label="失败" value="failed"/></el-select></el-form-item><el-button>筛选</el-button></el-form><el-empty description="暂无 Trace 运维元数据"/></template><template v-else><div class="grid grid-cols-1 md:grid-cols-4 gap-4"><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">请求数</div><div class="text-2xl font-semibold mt-2">—</div></el-card><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">Input / Output Unit</div><div class="text-2xl font-semibold mt-2">—</div></el-card><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">失败率</div><div class="text-2xl font-semibold mt-2">—</div></el-card><el-card shadow="never"><div class="text-sm text-[var(--el-text-color-secondary)]">延迟</div><div class="text-2xl font-semibold mt-2">—</div></el-card></div><el-alert title="用量统计接口尚未接入；此处不展示未经后端确认的成本数据。" type="info" show-icon class="mt-5"/></template></el-card><el-drawer v-model="detail" title="作业详情" size="480px"><el-alert title="Prompt / Response / Credential 默认隐藏，仅展示阶段状态。" type="warning" show-icon/><el-steps direction="vertical" class="mt-5"><el-step title="排队"/><el-step title="构建上下文"/><el-step title="Provider 请求 / Tool Call"/><el-step title="后处理"/><el-step title="持久化"/></el-steps></el-drawer></main></template>
